/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// TAMRebatePostDateTransactionFinancial extension to handles posting of lines, amounts and tax information
/// </summary>
[ExtensionOf(classStr(TAMRebatePostDateTransactionFinancial))]
final class METTAMRebatePostDateTransactionFinancial_Extension
{
    private NoYesId metFollowTransItemGSTGroup;

}

Method.Source:
/// CB201_RebatesExtension_GSTchanges
/// <summary>
/// Get posting amoutn query
/// </summary>
/// <param name = "_rebateDateTrans">TAMRebateDateTrans</param>
/// <returns>query</returns>
protected Query getPostingAmountQuery(TAMRebateDateTrans _rebateDateTrans)
{
    Query postingAmountQuery;

    postingAmountQuery = next getPostingAmountQuery(_rebateDateTrans);

    metFollowTransItemGSTGroup = createDocument.getRebatePosting().METFollowTransItemGSTGroup;

    if (metFollowTransItemGSTGroup && _rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        createDocument.parmRebateDateTrans(_rebateDateTrans);

        postingAmountQuery = new Query();

        QueryBuildDataSource rebateTransDataSource = postingAmountQuery.addDataSource(tableNum(TAMRebateTrans));
        rebateTransDataSource.addSelectionField(fieldNum(TAMRebateTrans, PostingAmount), SelectionField::Sum);

        if (rebateDeal.RebateReconciliation == TAMRebateReconciliation::Deal)
        {
            rebateTransDataSource.addGroupByAndSelectionField(fieldNum(TAMRebateTrans, RefCompanyId));
        }

        rebateTransDataSource.addGroupByAndSelectionField(fieldNum(TAMRebateTrans, METTaxItemGroup));

        if (rebateParameters.ProcessByDimension)
        {
            rebateTransDataSource.addGroupByAndSelectionField(fieldNum(TAMRebateTrans, DefaultDimension));
        }

        rebateTransDataSource.addRange(fieldNum(TAMRebateTrans, RebateTransId)).value(SysQuery::value(_rebateDateTrans.RebateTransId));

        if (rebateParameters.UseClaimProcess && _rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate)
        {
            rebateTransDataSource.addRange(fieldNum(TAMRebateTrans, Claimed)).value(SysQuery::value(NoYes::Yes));
        }
    }

    return postingAmountQuery;
}

/// CB201_RebatesExtension_GSTchanges
/// <summary>
/// Get posting amount key for rebate trans 
/// </summary>
/// <param name = "_rebateTrans">TAMRebateTrans</param>
/// <returns>container</returns>
protected container getPostingAmountMapKeyForRebateTrans(TAMRebateTrans _rebateTrans)
{
    container key = next getPostingAmountMapKeyForRebateTrans(_rebateTrans);
    TAMRebateDateTrans rebateDateTrans = createDocument.parmRebateDateTrans();

    if (metFollowTransItemGSTGroup && rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        key = [_rebateTrans.RefCompanyId, _rebateTrans.DefaultDimension, _rebateTrans.METTaxItemGroup];
    }

    return key;
}

/// CB201_RebatesExtension_GSTchanges
/// <summary>
/// Create line for document
/// </summary>
/// <param name = "_postingAmount">Posting amount based on query</param>
/// <param name = "_postingAmountMapKey">Posting amount container key</param>
protected void createLineForDocument(Amount _postingAmount, container _postingAmountMapKey)
{
    if (metFollowTransItemGSTGroup && conLen(_postingAmountMapKey) > 0)
    {
        TaxItemGroup itemSalesTaxGroup = conPeek(_postingAmountMapKey, 3);
        createDocument.parmItemSalesTaxGroup(itemSalesTaxGroup);
    }

    next createLineForDocument(_postingAmount, _postingAmountMapKey);
}
